import { React, useState, useEffect, Fragment, useCallback } from "react"
import axios from "axios"
import { trackPromise } from "react-promise-tracker"
import ShowSpinner from "./components/ShowSpinner"


const PartnersLeave = props => {
  const { currentRacf, setDisplayAlert, convertToLocal } = props 
  
  const [partnersList, setPartnersList] = useState([])
    
  const [deptList, setDeptList] = useState([])
  const [startDate, setStartDate] = useState(Date.now())

  const [deptPartnersList, setDeptPartnersList] = useState([])

  const [dept, setDept] = useState("ALL")
  
  const headingColor = document.querySelector(".partnersLeave_heading_color")
      
  function sortPartenrsList(list, order) {    
    const nList = list  
    if (order === "asc") {
      nList.sort(function (a, b) {
        return a.staff > b.staff ? 1 : -1
      })
    } else if (order === "desc") {
      nList.sort(function (a, b) {
        return a.staff < b.staff ? 1 : -1
      })
    }
    return nList
  }
  
  const refreshPartnersLeave = useCallback(() => {

    if (!currentRacf) {
       return
    }

    if (headingColor) {
      headingColor.style.borderColor = "green"
    }
   

    trackPromise(

      axios({
        url: "eleave/api/partnersleave",
        method: "POST",
        headers: {
          "Content-type": "application/json",
          api: "yes"
        },
        data: JSON.stringify({ racf: currentRacf, localTime: convertToLocal(startDate)})
      })
        .then(response => response.data)
        .then(response => {                    
          
   
          if (headingColor) {
            headingColor.style.borderColor = "red"
          }
         
          const partnersList = sortPartenrsList(response['result'], "asc")          
          // 
          
          const deptSet = new Set(partnersList.map(obj => obj.dept));
          const deptList = Array.from(deptSet);
          setDeptList(deptList)
          
          //console.log('deptlist', deptList); // Output: ["REG", "REG2"]          
          //console.log('partnersList', partnersList)

          setPartnersList(partnersList)                                       
    
 
        })
        .catch(error => {
          setDisplayAlert({ message: error.response.data.error_message, position: 4, timeout: 3000, color: "alert__red" })
          //console.log(error)          
        }),
      "partnersLeave"
    )
    

    return () => {
      setPartnersList(null) // This worked for me      
    }
    

  }, [currentRacf, setDisplayAlert, convertToLocal, startDate, headingColor])


  useEffect(() => {    
    const deptPartnersList = (dept !== "ALL") ? partnersList.filter(x => x.dept === dept) : partnersList //dept           
    setDeptPartnersList(deptPartnersList)    
  }, [partnersList, dept])
  
  useEffect(() => {
    refreshPartnersLeave()
  }, [currentRacf, refreshPartnersLeave])

 
  const back14Days = () => {    
      var new_d = startDate - (14 * 1000 * 60 * 60 * 24)        
      setStartDate(new_d)            
  }

  const next14Days = () => {    
      var new_d = startDate + (14 * 1000 * 60 * 60 * 24)        
      setStartDate(new_d)            
  }
  

  const handleSelectDept =  event => {    
    const { value } = event.target           

    const deptPartnersList = (value !== "ALL") ? partnersList.filter(x => x.dept === value) : partnersList  //dept 
    setDeptPartnersList(deptPartnersList)    
    setDept(value)
    
  }  

  const gotoPowerBI = () => {    
  
    const url = "https://app.powerbi.com/links/vbR2CwB5_7?ctid=42ab9b91-5029-47c6-8f78-38a33f843520&pbi_source=linkShare"
    const newWindow = window.open(url, "_blank", "noopener,noreferrer")
    if (newWindow) newWindow.opener = null
    
  }

  return (
    <Fragment>
      <div>
        <div>                  
            <div className="patnersLeave_heading_grid">                                 
                <div>Partners Status from&nbsp;<span className="partnersLeave_heading_color"> { convertToLocal(startDate) }</span>&nbsp;</div>                                     
                <div>Select department :</div>                  
                <select style={{width: '10rem'}} onChange={handleSelectDept} id="selectDeptOption" className="clickable" 
                      value = {dept}
                      >        
                      <option value="ALL">ALL</option>
                      {deptList.map((x, index) => (
                        <option key={index} value={x}>
                        {x}
                      </option>
                      ))}      
                </select>
                <button onClick={() => {gotoPowerBI()}} style={{ width: '80%' }}>Partners Balance</button>
            </div>
         
          
            <table id="partnersLeave_Table"> 
              <tbody>

                <tr className="partnersLeave_grid">                          
                  <th>Partners</th>                                                
                  <th className="partnersLeave_grid_notation">                          
                      <div className="partnersLeaveInner2_dayoff partnersLeaveInner2_mini"></div>                      
                      <div>Days Off (Holidays and Leaves)</div>
                      <div className="partnersLeaveInner2_workday partnersLeaveInner2_mini"></div>                                             
                      <div>Normal Working Days</div>
                      <div className="partnersLeaveInner2_pending partnersLeaveInner2_mini"></div>                                             
                      <div>Pending for Approval</div>    
                      <div></div>
                      <div>
                          <button onClick={() => {back14Days()}}>Back 14 days</button>
                      </div>
                      <div></div>
                      <div>
                        <button onClick={() => {next14Days()}}>Next 14 days</button>                      
                      </div>               
                  </th>
                </tr>                   

                {deptPartnersList && deptPartnersList.map((x, index) => (                    
                      <tr key={index} className="partnersLeave_grid">                                                                   

                          <td>{x.staff}</td>                 
                          <td className="partnersLeaveInner2_grid">

                              <div className="partnersLeaveInner2_header" >&nbsp;</div>
                              { x.partners['partnersDOM'].map((y, index2) => (
                                  <div key={index2} className="partnersLeaveInner2_header" >{y}</div>                                     
                              ))                               
                              }

                              <div className="partnersLeaveInner2_header" >&nbsp;</div>
                              { x.partners['partnersDOW'].map((y, index2) => (
                                  <div key={index2} className="partnersLeaveInner2_header" >{y}</div>    
                              ))                               
                              }
                              <div className="partnersLeaveInner2_header" >AM</div>
                              { x.partners['partnersAM'].map((y, index2) => (
                                    <div key={index2}  
                                      className={"partnersLeaveInner2_" + ( 
                                        y === "weekend" || y === "holiday"  ? "dayoff tooltip": 
                                        x.partners['partnersAMstatus'][index2] === "PENDING" ? "pending":                  
                                        y === "LVE01" || y === "LVE02" || y === "LVE04" || y === "LVE05" || y === "LVE06" || y.includes("LVE") ? "dayoff": 
                                        "workday")
                                      }                                                                                                                        
                                    >                                      
                                        {                                      
                                          y === "LVE01" ? "AL":
                                          y === "LVE02" ? "C/FL":
                                          y === "LVE03" ? "WFH":
                                          y === "LVE04" ? "SL":
                                          y === "LVE05" ? "SL": 
                                          y === "LVE06" ? "NP": 
                                          y.includes("LVE") ? "Others" :
                                          y === "holiday"  ? <div>P<span className="tooltiptext">{
                                            x.partners['partnersAMholiday'][index2] ? x.partners['partnersAMholiday'][index2] : "Public Holiday"
                                            }</span></div>: 
                                          <span>&nbsp;</span>                           
                                        }
                                     </div>    
                                ))                               
                              }

                              <div className="partnersLeaveInner2_header" >PM</div>
                              { x.partners['partnersPM'].map((y, index2) => (
                                    <div key={index2} 
                                      className={"partnersLeaveInner2_" + ( 
                                        y === "weekend" || y === "holiday"  ? "dayoff tooltip": 
                                        x.partners['partnersPMstatus'][index2] === "PENDING" ? "pending":                  
                                        y === "LVE01" || y === "LVE02" || y === "LVE04" || y === "LVE05" || y === "LVE06" || y.includes("LVE") ? "dayoff": 
                                        "workday")
                                      }                                                                                                                        
                                    >                                      
                                        {                                      
                                          y === "LVE01" ? "AL":
                                          y === "LVE02" ? "C/FL":
                                          y === "LVE03" ? "WFH":
                                          y === "LVE04" ? "SL":
                                          y === "LVE05" ? "SL":       
                                          y === "LVE06" ? "NP":     
                                          y.includes("LVE") ? "Others" :                                    
                                          y === "holiday"  ? <div>P<span className="tooltiptext">{
                                            x.partners['partnersPMholiday'][index2] ? x.partners['partnersPMholiday'][index2] : "Public Holiday"
                                          }</span></div>: 
                                          <span>&nbsp;</span>                           
                                        }
                                     </div>    
                                ))                               
                              }



                          </td>                                                            
                        </tr>                                                         
                  ))}
            </tbody>

          </table>   

          <ShowSpinner position={4} />            
          </div>
        </div>


    </Fragment>
  )
}

export default PartnersLeave
